ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.tfg_phase0.i20_assisted_annotation import content_id,validate_human_decisions
from src.tfg_phase0.i20_preparation import EXPECTED_IDS,canonical_bytes,sha256_text
def load(path):return json.loads(path.read_text(encoding='utf-8'))
def main():
 p=argparse.ArgumentParser();p.add_argument('--decisions',type=Path,required=True);p.add_argument('--scene-proposals',type=Path,required=True);p.add_argument('--annotation-proposals',type=Path,required=True);p.add_argument('--annotation-fixture',type=Path,required=True);p.add_argument('--scene-fixture',type=Path,required=True);p.add_argument('--output-root',type=Path,required=True);a=p.parse_args();decisions=load(a.decisions);scenes=load(a.scene_proposals);annotations=load(a.annotation_proposals);annotation_fixture=load(a.annotation_fixture);scene_fixture=load(a.scene_fixture);counts=validate_human_decisions(decisions,scene_proposals=scenes,annotation_proposals=annotations)
 if counts['pending'] or counts['rejected'] or counts['unresolved'] or len(decisions['decisions'])!=32:raise ValueError('decisiones assisted incompletas; completar manualmente antes de materializar')
